const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(v,d=2)=>v===null||v===undefined?'Unknown':Number(v).toLocaleString(undefined,{maximumFractionDigits:d});
const words=v=>String(v??'').replaceAll('_',' ');
const state={config:null,result:null,requestVersion:0,extraPatches:[]};
function message(text,error=false){$('message').hidden=false;$('message').textContent=text;$('message').classList.toggle('error',error);}
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let data;try{data=await r.json();}catch{throw Error('The engine returned an unreadable response. Check the local server.');}if(!r.ok)throw Error(data.error||`Request failed (${r.status})`);return data;}
function request(){
  const filters={};for(const [id,key] of [['manufacturer','manufacturer'],['category','category_id'],['availability','availability']])if($(id).value!=='')filters[key]=$(id).value;
  for(const [id,key] of [['min-price','min_price'],['max-price','max_price']])if($(id).value!=='')filters[key]=Number($(id).value);
  const patches=[...state.extraPatches];for(const [id,key] of [['patch-price','price_value'],['patch-weight','shipping_weight_g'],['patch-quantity','public_quantity']])if($(id).value!=='')patches.push({product_id:$('patch-id').value,field:key,value:Number($(id).value)});
  return {label:$('label').value,base:$('base').value,mode:$('mode').value,filters,analysis:{x:$('metric-x').value,y:$('metric-y').value},sources:JSON.parse($('sources').value),patches};
}
function changed(){state.requestVersion++;if(state.result)$('stale').hidden=false;try{const r=request();$('request-preview').textContent=JSON.stringify(r,null,2);$('source-count').textContent=Array.isArray(r.sources)?`${r.sources.length} added`:'Needs an array';}catch{$('request-preview').textContent='Additional sources contain invalid JSON. Fix the JSON before running.';}}
function defaults(){state.extraPatches=[];$('scenario-box').open=false;for(const id of ['manufacturer','category','availability','min-price','max-price','patch-price','patch-weight','patch-quantity'])$(id).value='';$('base').value='workspace';$('mode').value='observed';$('metric-x').value='shipping_weight_g';$('metric-y').value='price_value';$('sources').value='[]';$('patch-id').value='6006';}
function preset(name){defaults();if(name==='baseline')$('label').value='Real Adafruit baseline';if(name==='scenario'){$('label').value='Pico 2 price and weight what-if';$('mode').value='simulation';$('manufacturer').value='Raspberry Pi Foundation';$('patch-price').value='12.50';$('patch-weight').value='8.20';$('scenario-box').open=true;}if(name==='messy'){$('label').value='Hypothetical messy specification CSV';$('mode').value='simulation';$('manufacturer').value='Raspberry Pi Foundation';$('sources').value=JSON.stringify([{id:'DEMO_MESSY_CLAIMS',kind:'specifications',label:'Hypothetical test claims, duplicates and an unknown ID',captured_at:'2026-10-24',csv:'record_id,product_id,property,value,unit\nclaim-1, ADA6006 ,clock,160,MHz\nclaim-1, ADA6006 ,clock,160,MHz\nclaim-2,https://www.adafruit.com/product/4864,sram,264,kB\nclaim-3,99999999,sram,64,kB\n'}],null,2);}changed();}
function download(id,file){return `/api/engine/download?${new URLSearchParams({run:id,file})}`;}
function metricLabel(id){return state.config.metrics.find(m=>m.id===id)?.label||id;}
function show(result){
  state.result=result;$('output').hidden=false;$('stale').hidden=true;$('simulation').hidden=result.mode!=='simulation';$('result-label').textContent=result.label;
  $('result-meta').textContent=`${result.run_id} · ${result.mode==='simulation'?'Simulation':'Real / user-supplied inputs'} · baseline revision ${result.base_revision} · ${result.created_at}`;
  const fields=[['Products in loaded model','total_products'],['Products after filters','selected_products'],['Complete pairs','n'],['Pearson r','r'],['Excluded from correlation','excluded_products'],['Source rows in loaded model','input_rows'],['Duplicates suppressed','duplicate_rows_suppressed'],['Unmatched rows, whole model','unmatched_rows'],['Specification conflicts, whole model','conflicts']];
  $('summary').innerHTML=fields.map(([label,key])=>{const a=result.baseline[key],b=result.summary[key],d=key==='r'?4:0;return `<tr><td>${esc(label)}</td><td class="number">${number(a,d)}</td><td class="number">${number(b,d)}</td><td class="number">${a===null||b===null?'—':number(b-a,d)}</td></tr>`;}).join('');
  $('analysis-title').textContent=`${metricLabel(result.analysis.x)} × ${metricLabel(result.analysis.y)}`;
  $('r-value').textContent=result.analysis.r===null?'Not calculated':`r = ${Number(result.analysis.r).toFixed(4)}`;
  $('pair-count').textContent=`${number(result.analysis.n,0)} complete pairs from ${number(result.summary.selected_products,0)} selected products.`;
  $('excluded').textContent=`${result.analysis.reason?result.analysis.reason+'. ':''}Exclusions: ${Object.entries(result.analysis.exclusions).map(([key,n])=>`${number(n,0)} ${words(key)}`).join('; ')||'none'}.`;
  $('interpretation').textContent=result.interpretation;$('cohort').textContent=`Comparable cohort: ${result.analysis.cohort||'No eligible cohort'}`;
  $('changes').innerHTML=result.changes.map(c=>`<tr><td>${esc(c.product_id)}${!c.in_selected_output?'<small>Outside selected output</small>':''}</td><td>${esc(words(c.field))}</td><td>${esc(c.before===null?'Unknown':c.before)}</td><td>${esc(c.after===null?'Unknown':c.after)}</td><td>${esc(words(c.basis))}</td></tr>`).join('')||'<tr><td colspan="5">No field values changed.</td></tr>';
  $('changes-note').textContent=`${number(result.changes_total,0)} field changes across the loaded model.${result.changes_total>100?' The first 100 are shown; the complete list is in the export.':''}`;
  $('products').innerHTML=result.products.map(p=>`<tr class="${p.scenario_modified?'modified':''}"><td class="product-name">${esc(p.product_name)}<small>${esc(p.product_id)}${p.scenario_modified?' · hypothetical changes applied':''}</small></td><td class="number">${number(p.price_value)}</td><td class="number">${number(p.shipping_weight_g)}</td><td class="number">${number(p.sram_kb,0)}</td><td class="number">${number(p.clock_mhz)}</td><td>${esc(words(p.availability))}</td><td>${esc(words(p.decision))}</td></tr>`).join('')||'<tr><td colspan="7">No products match these inputs and filters.</td></tr>';
  $('products-note').textContent=`Showing ${result.products.length} of ${number(result.products_total,0)} products. Excel and CSV contain every selected product. Missing values remain unknown. Prices use source units.`;
  $('products-csv').href=download(result.run_id,'products.csv');
  $('conflicts').innerHTML=result.conflicts.map(c=>`<div class="issue"><strong>${esc('ADA:'+c.product_id)} · ${esc(words(c.property))}</strong><p>Retained values: ${esc([...new Set(c.claims.map(r=>r.normalized.value))].join(', '))}</p><p>Selected: ${esc(c.selected===null?'Unresolved':`${c.selected.value} ${c.selected.unit}`)}</p><p>${esc(c.basis)}</p></div>`).join('')||'<p class="muted">No conflicts in the selected products.</p>';
  $('unmatched').innerHTML=result.quarantine.map(q=>`<div class="issue"><strong>${esc(q.raw.product_id||q.raw.product_name||'Unknown identity')}</strong><p>${esc(q.reason)}</p><p>Source: ${esc(q.source_id)}${q.candidate_ids.length?' · review candidates: '+esc(q.candidate_ids.join(', ')):''}</p></div>`).join('')||'<p class="muted">Every distinct input row has an exact product match.</p>';
  if(result.quarantine_total>50)$('unmatched').insertAdjacentHTML('beforeend',`<p class="note">Showing 50 of ${number(result.quarantine_total,0)}. Download the full unmatched CSV.</p>`);
  $('downloads').innerHTML=[['products.csv','Simplified products CSV'],['changes.csv','Field changes CSV'],['correlations.csv','Manufacturer correlations CSV'],['evidence.csv','Linked evidence CSV'],['unmatched.csv','Unmatched CSV'],['sources.csv','Source register CSV'],['result.json','Full result JSON'],['inputs.json','Original input snapshot JSON']].map(([file,label])=>`<a href="${esc(download(result.run_id,file))}">${esc(label)}</a>`).join('');
  $('saved-request').textContent=JSON.stringify(result.request,null,2);$('excel').disabled=false;
}
async function history(){const runs=await api('/api/engine/runs');$('history').innerHTML=runs.map(r=>`<button type="button" data-run="${esc(r.run_id)}">${esc(r.label)}<small>${esc(r.mode)} · ${number(r.summary.selected_products,0)} products · r ${r.summary.r===null?'unavailable':Number(r.summary.r).toFixed(4)} · ${esc(r.created_at)}</small></button>`).join('')||'<p class="muted">Your first run will appear here.</p>';}
function restore(r){defaults();$('label').value=r.label||'Adafruit run';$('base').value=r.base||'workspace';$('mode').value=r.mode||'observed';const f=r.filters||{};for(const [id,key] of [['manufacturer','manufacturer'],['category','category_id'],['availability','availability'],['min-price','min_price'],['max-price','max_price']])$(id).value=f[key]??'';$('metric-x').value=r.analysis?.x||'shipping_weight_g';$('metric-y').value=r.analysis?.y||'price_value';$('sources').value=JSON.stringify(r.sources||[],null,2);const patches=r.patches||[];if(patches.length){const ids=new Set(patches.map(p=>p.product_id));if(ids.size===1){$('patch-id').value=patches[0].product_id;for(const p of patches){const id={price_value:'patch-price',shipping_weight_g:'patch-weight',public_quantity:'patch-quantity'}[p.field];if(id)$(id).value=p.value;}}else state.extraPatches=[...patches];}changed();}
$('run-form').addEventListener('submit',async event=>{event.preventDefault();let r;try{r=request();}catch(e){message(e.message,true);return;}$('controls').disabled=true;$('run').textContent='Processing in C++…';message('Validating, cleaning, linking and analyzing the inputs…');try{show(await api('/api/engine/run',r));message('Run saved. Inspect its outputs or download Excel.');await history();}catch(e){message(e.message,true);}finally{$('controls').disabled=false;$('run').textContent='Run engine';}});
$('excel').addEventListener('click',async()=>{if(!state.result)return;const id=state.result.run_id;$('excel').disabled=true;$('excel').textContent='Formatting Excel…';try{const result=await api('/api/engine/excel',{run_id:id});const a=document.createElement('a');a.href=result.url;a.download='';document.body.append(a);a.click();a.remove();message('The Excel workbook is ready. Its numbers belong to the saved run.');}catch(e){message(e.message,true);}finally{$('excel').disabled=false;$('excel').textContent='Download Excel workbook';}});
document.addEventListener('click',async e=>{const presetButton=e.target.closest('[data-preset]');if(presetButton)preset(presetButton.dataset.preset);const run=e.target.closest('[data-run]');if(run){try{const r=await api(`/api/engine/run?${new URLSearchParams({id:run.dataset.run})}`);restore(r.request);show(r);message('Loaded the saved results without rerunning the model.');}catch(error){message(error.message,true);}}});
$('controls').addEventListener('input',e=>{if(['patch-price','patch-weight','patch-quantity'].includes(e.target.id)&&e.target.value!=='')$('mode').value='simulation';changed();});$('controls').addEventListener('change',changed);
$('source-files').addEventListener('change',async()=>{try{const sources=JSON.parse($('sources').value);if(!Array.isArray(sources))throw Error('Additional sources must be a JSON array.');let added=[];for(const file of $('source-files').files){if(file.size>19*1024*1024)throw Error('Choose files smaller than 19 MB.');const text=await file.text();if(file.name.toLowerCase().endsWith('.csv')){if(!$('csv-date').value)throw Error('Choose a CSV capture date.');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));const hash=[...new Uint8Array(digest)].map(n=>n.toString(16).padStart(2,'0')).join('').slice(0,12);added.push({id:`UPLOAD_${$('csv-kind').value}_${hash}`,kind:$('csv-kind').value,label:file.name,captured_at:$('csv-date').value,csv:text});}else{const value=JSON.parse(text);added.push(...(Array.isArray(value)?value:Array.isArray(value.sources)?value.sources:[value]));}}if(sources.length+added.length>20)throw Error('Use at most 20 additional sources per run.');$('sources').value=JSON.stringify([...sources,...added],null,2);changed();message(`Added ${added.length} source files. C++ will parse and validate them when you run the engine.`);}catch(e){message(e.message,true);}finally{$('source-files').value='';}});
(async()=>{state.config=await api('/api/engine/config');$('connection').textContent='C++ engine connected';$('capture').textContent=`${number(state.config.products,0)} real products · catalog captured ${state.config.catalog_captured_at} · workspace revision ${state.config.base_revision}`;$('manufacturer').insertAdjacentHTML('beforeend',state.config.manufacturers.map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join(''));$('category').insertAdjacentHTML('beforeend',Object.entries(state.config.category_labels).sort((a,b)=>a[1].localeCompare(b[1])).map(([id,name])=>`<option value="${esc(id)}">${esc(name)} (${esc(id)})</option>`).join(''));for(const id of ['metric-x','metric-y'])$(id).innerHTML=state.config.metrics.map(m=>`<option value="${esc(m.id)}">${esc(m.label)}</option>`).join('');$('csv-date').value=new Date().toISOString().slice(0,10);preset('baseline');await history();})().catch(e=>message(e.message,true));
